package com.gerenciadorrural.modules.herd.infrastructure;
import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.TenantId; import org.springframework.jdbc.core.namedparam.*; import org.springframework.stereotype.Repository; import java.time.*; import java.util.*;
@Repository public class JdbcHerdReproductionRepository implements HerdReproductionRepository {private final NamedParameterJdbcTemplate j;public JdbcHerdReproductionRepository(NamedParameterJdbcTemplate j){this.j=j;}private MapSqlParameterSource p(TenantId t,UUID f){return new MapSqlParameterSource("tenant",t.value()).addValue("farm",f);} public Optional<Pregnancy> find(TenantId t,UUID f,UUID id,boolean lock){return j.query("select * from app.animal_pregnancies where tenant_id=:tenant and farm_id=:farm and id=:id"+(lock?" for update":""),p(t,f).addValue("id",id),this::map).stream().findFirst();}public Optional<Pregnancy> findByOperation(TenantId t,UUID f,UUID op){return j.query("select * from app.animal_pregnancies where tenant_id=:tenant and farm_id=:farm and operation_id=:op",p(t,f).addValue("op",op),this::map).stream().findFirst();}public Pregnancy insert(Pregnancy x){return j.query("insert into app.animal_pregnancies(id,tenant_id,farm_id,mother_animal_id,service_type,service_on,sire_reference,expected_calving_on,operation_id,command_payload,created_by) values(:id,:tenant,:farm,:mother,:type,:service,:sire,:due,:op,:payload,:actor) returning *",new MapSqlParameterSource().addValue("id",x.id()).addValue("tenant",x.tenantId().value()).addValue("farm",x.farmId()).addValue("mother",x.motherAnimalId()).addValue("type",x.serviceType().name()).addValue("service",x.serviceOn()).addValue("sire",x.sireReference()).addValue("due",x.expectedCalvingOn()).addValue("op",x.operationId()).addValue("payload",x.commandPayload()).addValue("actor",null),this::map).getFirst();} public Optional<Pregnancy> transition(TenantId t,UUID f,UUID id,long v,PregnancyStatus s,LocalDate d,PregnancyTerminationReason r,UUID calf){return j.query("update app.animal_pregnancies set status=:status,confirmed_on=case when :status='CONFIRMED' then :date else confirmed_on end,ended_on=case when :status in ('TERMINATED','CALVED') then :date else ended_on end,termination_reason=:reason,calf_animal_id=:calf,version=version+1,updated_at=current_timestamp where tenant_id=:tenant and farm_id=:farm and id=:id and version=:version returning *",p(t,f).addValue("id",id).addValue("version",v).addValue("status",s.name()).addValue("date",d).addValue("reason",r==null?null:r.name()).addValue("calf",calf),this::map).stream().findFirst();}public List<Pregnancy> list(TenantId t,UUID f,UUID mother,int size,long offset){return j.query("select * from app.animal_pregnancies where tenant_id=:tenant and farm_id=:farm and mother_animal_id=:mother order by service_on desc,id desc limit :size offset :offset",p(t,f).addValue("mother",mother).addValue("size",size).addValue("offset",offset),this::map);}private Pregnancy map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new Pregnancy(r.getObject("id",UUID.class),new TenantId(r.getObject("tenant_id",UUID.class)),r.getObject("farm_id",UUID.class),r.getObject("mother_animal_id",UUID.class),ReproductionServiceType.valueOf(r.getString("service_type")),r.getObject("service_on",LocalDate.class),r.getString("sire_reference"),r.getObject("expected_calving_on",LocalDate.class),PregnancyStatus.valueOf(r.getString("status")),r.getObject("confirmed_on",LocalDate.class),r.getObject("ended_on",LocalDate.class),r.getString("termination_reason")==null?null:PregnancyTerminationReason.valueOf(r.getString("termination_reason")),r.getObject("calf_animal_id",UUID.class),r.getObject("operation_id",UUID.class),r.getString("command_payload"),r.getLong("version"));}}
